import hashlib
import os
import tempfile
from dataclasses import dataclass
from pathlib import Path
from urllib.parse import quote

import requests

DEFAULT_TIMEOUT = 10
_TMP_PREFIX = ".syncbox-pull-tmp-"


class PushError(Exception):
    pass


class PullError(Exception):
    pass


class StatusError(Exception):
    pass


@dataclass
class PushResult:
    uploaded: list
    unchanged: list


@dataclass
class PullResult:
    downloaded: list
    unchanged: list


@dataclass
class StatusResult:
    to_upload: list
    to_download: list
    unchanged: list


def sha256_file(path) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def scan_files(root: Path) -> dict:
    """Map POSIX relative key -> absolute on-disk path for every regular file under root."""
    files = {}
    for dirpath, _dirnames, filenames in os.walk(root, followlinks=False):
        for name in filenames:
            full = os.path.join(dirpath, name)
            if not os.path.isfile(full):
                continue
            key = Path(os.path.relpath(full, root)).as_posix()
            files[key] = full
    return files


def fetch_remote_index(server_url: str, session: requests.Session) -> dict:
    response = session.get(f"{server_url}/blobs", timeout=DEFAULT_TIMEOUT)
    response.raise_for_status()
    return {item["key"]: item["sha256"] for item in response.json()}


def upload_blob(server_url: str, key: str, path, session: requests.Session) -> None:
    url = f"{server_url}/blobs/{quote(key, safe='/')}"
    with open(path, "rb") as f:
        data = f.read()
    response = session.put(
        url,
        data=data,
        timeout=DEFAULT_TIMEOUT,
        headers={"Content-Type": "application/octet-stream"},
    )
    if response.status_code != 201:
        raise PushError(f"failed to upload {key}: server returned {response.status_code}")


def push(dir_path, server_url: str, session: requests.Session = None) -> PushResult:
    root = Path(dir_path)
    if not root.is_dir():
        raise PushError(f"{dir_path} is not a directory")

    server_url = server_url.rstrip("/")
    owns_session = session is None
    session = session or requests.Session()
    try:
        local_files = scan_files(root)
        remote_index = fetch_remote_index(server_url, session)

        uploaded = []
        unchanged = []
        for key in sorted(local_files):
            sha256 = sha256_file(local_files[key])
            if remote_index.get(key) == sha256:
                unchanged.append(key)
                continue
            upload_blob(server_url, key, local_files[key], session)
            uploaded.append(key)

        return PushResult(uploaded=uploaded, unchanged=unchanged)
    finally:
        if owns_session:
            session.close()


def _local_path_for_key(root: Path, key: str) -> Path:
    """Resolve a server-provided key to a path inside root.

    Mirrors the server's own key validation: the server should never hand
    out a key containing '..'/'.' segments, but pull writes to the local
    filesystem based on that key, so it re-checks rather than trusting a
    buggy or compromised server to keep every write inside root.
    """
    parts = key.split("/")
    if not key or any(part in ("", ".", "..") for part in parts):
        raise PullError(f"server returned an unsafe key: {key!r}")
    candidate = root.joinpath(*parts)
    real_root = os.path.realpath(root)
    real_candidate = os.path.realpath(candidate)
    if os.path.commonpath([real_root, real_candidate]) != real_root:
        raise PullError(f"server returned a key that escapes {root}: {key!r}")
    return candidate


def download_blob(server_url: str, key: str, dest: Path, session: requests.Session) -> None:
    url = f"{server_url}/blobs/{quote(key, safe='/')}"
    response = session.get(url, timeout=DEFAULT_TIMEOUT)
    if response.status_code != 200:
        raise PullError(f"failed to download {key}: server returned {response.status_code}")

    dest.parent.mkdir(parents=True, exist_ok=True)
    fd, tmp_path = tempfile.mkstemp(dir=dest.parent, prefix=_TMP_PREFIX)
    try:
        with os.fdopen(fd, "wb") as f:
            f.write(response.content)
        os.replace(tmp_path, dest)
    except OSError:
        os.remove(tmp_path)
        raise


def pull(dir_path, server_url: str, session: requests.Session = None) -> PullResult:
    root = Path(dir_path)
    if not root.is_dir():
        raise PullError(f"{dir_path} is not a directory")

    server_url = server_url.rstrip("/")
    owns_session = session is None
    session = session or requests.Session()
    try:
        local_files = scan_files(root)
        remote_index = fetch_remote_index(server_url, session)

        downloaded = []
        unchanged = []
        for key in sorted(remote_index):
            sha256 = remote_index[key]
            local_path = local_files.get(key)
            if local_path is not None and sha256_file(local_path) == sha256:
                unchanged.append(key)
                continue
            dest = _local_path_for_key(root, key)
            download_blob(server_url, key, dest, session)
            downloaded.append(key)

        return PullResult(downloaded=downloaded, unchanged=unchanged)
    finally:
        if owns_session:
            session.close()


def status(dir_path, server_url: str, session: requests.Session = None) -> StatusResult:
    """Dry-run comparison of local dir vs server: never writes anywhere."""
    root = Path(dir_path)
    if not root.is_dir():
        raise StatusError(f"{dir_path} is not a directory")

    server_url = server_url.rstrip("/")
    owns_session = session is None
    session = session or requests.Session()
    try:
        local_files = scan_files(root)
        remote_index = fetch_remote_index(server_url, session)
        local_hashes = {key: sha256_file(path) for key, path in local_files.items()}

        to_upload = sorted(
            key for key, sha256 in local_hashes.items() if remote_index.get(key) != sha256
        )
        to_download = sorted(
            key for key, sha256 in remote_index.items() if local_hashes.get(key) != sha256
        )
        unchanged = sorted(
            key for key, sha256 in local_hashes.items() if remote_index.get(key) == sha256
        )

        return StatusResult(to_upload=to_upload, to_download=to_download, unchanged=unchanged)
    finally:
        if owns_session:
            session.close()

import sys

import requests

from .client import PullError, PushError, StatusError, pull, push, status
from .config import ClientConfigError, parse_args

_NOT_IMPLEMENTED = ("sync",)


def main(argv=None) -> int:
    argv = sys.argv[1:] if argv is None else argv
    try:
        args = parse_args(argv)
    except ClientConfigError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    if args.command in _NOT_IMPLEMENTED:
        print(
            f"syncbox: '{args.command}' is not implemented yet "
            "(planned for a future ticket)",
            file=sys.stderr,
        )
        return 2

    if args.command == "pull":
        return _run_pull(args)

    if args.command == "status":
        return _run_status(args)

    return _run_push(args)


def _run_push(args) -> int:
    try:
        result = push(args.dir, args.server)
    except requests.exceptions.RequestException as exc:
        print(f"syncbox: could not reach server {args.server}: {exc}", file=sys.stderr)
        return 1
    except PushError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.uploaded:
        print(f"uploaded {key}")
    print(
        f"push complete: {len(result.uploaded)} uploaded, "
        f"{len(result.unchanged)} unchanged"
    )
    return 0


def _run_pull(args) -> int:
    try:
        result = pull(args.dir, args.server)
    except requests.exceptions.RequestException as exc:
        print(f"syncbox: could not reach server {args.server}: {exc}", file=sys.stderr)
        return 1
    except PullError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    for key in result.downloaded:
        print(f"downloaded {key}")
    print(
        f"pull complete: {len(result.downloaded)} downloaded, "
        f"{len(result.unchanged)} unchanged"
    )
    return 0


def _run_status(args) -> int:
    try:
        result = status(args.dir, args.server)
    except requests.exceptions.RequestException as exc:
        print(f"syncbox: could not reach server {args.server}: {exc}", file=sys.stderr)
        return 1
    except StatusError as exc:
        print(f"syncbox: {exc}", file=sys.stderr)
        return 1

    if not result.to_upload and not result.to_download:
        print("status: no differences, local and server are in sync")
        return 0

    if result.to_upload:
        print(f"would upload (local -> server): {len(result.to_upload)}")
        for key in result.to_upload:
            print(f"  upload   {key}")
    if result.to_download:
        print(f"would download (server -> local): {len(result.to_download)}")
        for key in result.to_download:
            print(f"  download {key}")
    print(
        f"status complete: {len(result.to_upload)} to upload, "
        f"{len(result.to_download)} to download, {len(result.unchanged)} unchanged"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

import hashlib
import os
import tempfile
from datetime import datetime, timezone

from flask import Flask, Response, abort, jsonify, request

from .config import Config

_TMP_PREFIX = ".syncbox-tmp-"
_ITEM_PREFIX = "/blobs/"


class InvalidKey(Exception):
    pass


def _resolve_blob_path(root: str, key: str) -> str:
    """Resolve `key` to an on-disk path inside `root`.

    Raises InvalidKey if the key is malformed (empty, absolute, containing
    '.'/'..' segments), can't be represented as a filesystem path, or -
    once symlinks are resolved - would land outside `root` (e.g. via a
    symlink planted inside the storage directory).
    """
    if not key:
        raise InvalidKey("key must not be empty")
    if "\x00" in key:
        raise InvalidKey("key must not contain a NUL byte")
    parts = key.split("/")
    if any(part in ("", ".", "..") for part in parts):
        raise InvalidKey("key must not contain empty, '.', or '..' segments")
    try:
        key.encode("utf-8", errors="strict")
        candidate = os.path.join(root, *parts)
        real_root = os.path.realpath(root)
        real_candidate = os.path.realpath(candidate)
        escapes_root = os.path.commonpath([real_root, real_candidate]) != real_root
    except (UnicodeError, ValueError, OSError) as exc:
        raise InvalidKey("key is not representable on this filesystem") from exc
    if escapes_root:
        raise InvalidKey("key escapes the storage root")
    return candidate


def _sha256_file(path: str) -> str:
    digest = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            digest.update(chunk)
    return digest.hexdigest()


def create_app(config: Config) -> Flask:
    app = Flask(__name__)
    app.config["SYNCBOX_CONFIG"] = config

    root = config.data_dir
    os.makedirs(root, exist_ok=True)

    @app.get("/healthz")
    def healthz():
        return "", 200

    @app.get("/blobs")
    def list_blobs():
        items = []
        for dirpath, _dirnames, filenames in os.walk(root):
            for name in filenames:
                if name.startswith(_TMP_PREFIX):
                    continue
                full = os.path.join(dirpath, name)
                rel = os.path.relpath(full, root).replace(os.sep, "/")
                try:
                    st = os.stat(full)
                    sha256 = _sha256_file(full)
                except OSError:
                    continue
                modified_at = datetime.fromtimestamp(
                    st.st_mtime, tz=timezone.utc
                ).strftime("%Y-%m-%dT%H:%M:%SZ")
                items.append(
                    {
                        "key": rel,
                        "size": st.st_size,
                        "sha256": sha256,
                        "modified_at": modified_at,
                    }
                )
        return jsonify(items), 200

    def get_blob(key):
        try:
            path = _resolve_blob_path(root, key)
        except InvalidKey as exc:
            return jsonify(error=str(exc)), 400
        try:
            with open(path, "rb") as f:
                data = f.read()
        except OSError:
            abort(404)
        return Response(data, mimetype="application/octet-stream")

    def put_blob(key):
        try:
            dest = _resolve_blob_path(root, key)
        except InvalidKey as exc:
            return jsonify(error=str(exc)), 400

        data = request.get_data()
        dest_dir = os.path.dirname(dest)
        tmp_path = None
        try:
            os.makedirs(dest_dir, exist_ok=True)
            # The temp file lives in dest_dir itself (not a shared tmp dir)
            # so it is always on the same filesystem as dest, guaranteeing
            # os.replace below is an atomic rename rather than a cross-device
            # copy - concurrent GETs on this key always see fully old or
            # fully new content, never a partial write.
            fd, tmp_path = tempfile.mkstemp(dir=dest_dir, prefix=_TMP_PREFIX)
            with os.fdopen(fd, "wb") as f:
                f.write(data)
            os.replace(tmp_path, dest)
            tmp_path = None
        except OSError:
            return jsonify(error="key cannot be stored on this filesystem"), 400
        finally:
            if tmp_path is not None:
                try:
                    os.remove(tmp_path)
                except OSError:
                    pass

        return (
            jsonify(key=key, sha256=hashlib.sha256(data).hexdigest(), size=len(data)),
            201,
        )

    def delete_blob(key):
        try:
            path = _resolve_blob_path(root, key)
        except InvalidKey as exc:
            return jsonify(error=str(exc)), 400
        try:
            os.remove(path)
        except OSError:
            abort(404)
        return "", 204

    _blob_item_handlers = {"GET": get_blob, "PUT": put_blob, "DELETE": delete_blob}

    @app.before_request
    def dispatch_blob_item():
        # Routed manually (rather than via a Flask/Werkzeug URL rule) so that
        # arbitrary key values — including ones Werkzeug's own URL matcher
        # would special-case (encoded slashes, control characters, repeated
        # slashes, ".."/"." segments, an empty key) — all reach the same
        # validation instead of surfacing routing-layer status codes that
        # the API contract for /blobs/{key} doesn't declare.
        path = request.path
        if not path.startswith(_ITEM_PREFIX):
            return None
        handler = _blob_item_handlers.get(request.method)
        if handler is None:
            abort(405)
        key = path[len(_ITEM_PREFIX) :]
        return handler(key)

    return app

#!/usr/bin/env bash
set -euo pipefail
exec python3 -m syncbox_client.main "$@"

import pytest

from syncbox_client.config import ClientConfigError, parse_args


def test_requires_server():
    with pytest.raises(ClientConfigError):
        parse_args(["push", "/tmp/x"], env={})


def test_server_from_flag():
    args = parse_args(["push", "/tmp/x", "--server", "http://host:8080"], env={})
    assert args.command == "push"
    assert args.dir == "/tmp/x"
    assert args.server == "http://host:8080"


def test_server_from_env():
    args = parse_args(["push", "/tmp/x"], env={"SYNCBOX_SERVER": "http://env:8080"})
    assert args.server == "http://env:8080"


def test_flag_overrides_env():
    args = parse_args(
        ["push", "/tmp/x", "--server", "http://flag:8080"],
        env={"SYNCBOX_SERVER": "http://env:8080"},
    )
    assert args.server == "http://flag:8080"


@pytest.mark.parametrize("command", ["push", "pull", "sync", "status"])
def test_accepts_all_four_commands(command):
    args = parse_args([command, "/tmp/x", "--server", "http://host:8080"], env={})
    assert args.command == command


def test_rejects_unknown_command():
    with pytest.raises(SystemExit):
        parse_args(["frobnicate", "/tmp/x", "--server", "http://host:8080"], env={})

import pytest

from syncbox_server.config import ConfigError, load_config


def test_requires_data_dir():
    with pytest.raises(ConfigError):
        load_config([], env={})


def test_data_dir_from_flag():
    config = load_config(["--data-dir", "/tmp/x"], env={})
    assert config.data_dir == "/tmp/x"
    assert config.port == 8080


def test_data_dir_from_env():
    config = load_config([], env={"SYNCBOX_DATA_DIR": "/tmp/y"})
    assert config.data_dir == "/tmp/y"
    assert config.port == 8080


def test_flag_data_dir_overrides_env():
    config = load_config(
        ["--data-dir", "/tmp/flag"], env={"SYNCBOX_DATA_DIR": "/tmp/env"}
    )
    assert config.data_dir == "/tmp/flag"


def test_port_from_flag_overrides_env():
    config = load_config(
        ["--data-dir", "/tmp/x", "--port", "9090"],
        env={"SYNCBOX_PORT": "7070"},
    )
    assert config.port == 9090


def test_port_from_env():
    config = load_config(["--data-dir", "/tmp/x"], env={"SYNCBOX_PORT": "7070"})
    assert config.port == 7070


def test_invalid_port_env_raises():
    with pytest.raises(ConfigError):
        load_config(["--data-dir", "/tmp/x"], env={"SYNCBOX_PORT": "not-a-number"})

